#include "../boundary-kernel.cpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
static void require(bool b,const char*message){if(!b){std::fprintf(stderr,"boundary block failure %s\n",message);std::abort();}}
static void rectangle(SAInkPathCommand*out,double x){SAInkPathCommand a[5]={{SA_INK_MOVE,0,{x,0}},{SA_INK_LINE,0,{x+1,0}},{SA_INK_LINE,0,{x+1,1}},{SA_INK_LINE,0,{x,1}},{SA_INK_CLOSE,0,{}}};std::memcpy(out,a,sizeof a);}
int main(int argc,char**argv){uint32_t count=argc>2?uint32_t(std::strtoul(argv[2],nullptr,10)):32;require(count>=2&&count<=4096,"test count");FILE*f=argc>1?std::fopen(argv[1],"wb"):nullptr;if(argc>1)require(f,"output");
 SABoundaryBudget b{};b.max_commands=count*5+10;b.max_curves=count*4+16;b.max_pairs=count*8+100;b.max_cuts=count*16+1024;b.max_edges=count*8+32;b.max_leases=4;b.max_sources=count+4;b.max_paths=64;b.max_polynomial_degree=64;b.max_stored_bits=16384;b.max_polynomial_operations=50000000;b.max_limb_operations=10000000000ull;b.retained_bytes=(count>128?192u:80u)*1024*1024;b.workspace_bytes=(count>128?64u:80u)*1024*1024;
 std::vector<uint64_t>state((sa_boundary_state_bytes()+7)/8),arena((b.retained_bytes+b.workspace_bytes)/8);require(sa_boundary_initialize(state.data(),uint32_t(state.size()*8),87,arena.data(),uint32_t(arena.size()*8),&b)==0,"private owner");SABoundaryCapacity actual_capacity{};require(sa_boundary_capacity(state.data(),&actual_capacity)==0&&actual_capacity.backing_bytes==arena.size()*8&&actual_capacity.arena_usable_bytes==(count>128?256ull:128ull)*1024*1024&&actual_capacity.retained_limit_bytes==b.retained_bytes&&actual_capacity.workspace_limit_bytes==b.workspace_bytes,"admission uses actual buddy capacity not supplied bytes");SABoundaryPath path{};std::vector<SABoundarySourceBlock>sources(count);std::vector<SAInkPathCommand>commands(count*5);
 for(uint32_t i=0;i<count;i++){sources[i].key.words[0]=i+1;sources[i].first_command=i*5;sources[i].command_count=5;sources[i].affine[0]=sources[i].affine[3]=1;rectangle(commands.data()+i*5,i*3);}
 SABoundaryLease a{},next{};auto status=sa_boundary_prepare(state.data(),nullptr,&path,1,sources.data(),count,commands.data(),count*5,&a);if(status){const auto&o=*showai_boundary::owner(state.data());std::fprintf(stderr,"FULL_BLOCK_PREPARE_STATUS %u peak %llu live %llu\n",status,(unsigned long long)o.math.numbers.peak_bytes,(unsigned long long)o.math.numbers.live_bytes);}require(status==0,"full independent capture");SABoundaryBlocksSnapshot initial{},delta{};SABoundarySnapshot memory_report{};require(sa_boundary_snapshot(state.data(),a,&memory_report)==0,"memory report");std::fprintf(stderr,"BLOCK_ARENA_BYTES retained=%llu peak=%llu\n",(unsigned long long)memory_report.retained_peak_bytes,(unsigned long long)memory_report.arena_peak_bytes);require(sa_boundary_blocks_snapshot(state.data(),a,&initial)==0&&initial.base_generation==0&&initial.reset==1&&initial.block_count==count*4&&initial.change_count==count*4,"full reset metadata");
 std::vector<SABoundaryBlockChange>before(initial.change_count);require(sa_boundary_copy_block_changes(state.data(),a,0,initial.change_count,before.data(),initial.change_count)==0,"original actual blocks");const auto&old=static_cast<const showai_boundary::Owner*>(showai_boundary::owner(state.data()))->slots[a.slot].snapshot.get()->graph;
 SABoundarySourceMutation m{};m.source=sources.back();m.source.first_command=0;SAInkPathCommand changed[5];rectangle(changed,count*3+4);require(sa_boundary_update(state.data(),&a,&m,1,changed,5,&next)==0,"actual moved tail source");require(sa_boundary_blocks_snapshot(state.data(),next,&delta)==0&&delta.base_generation==a.generation&&delta.reset==0&&delta.block_count==count*4&&delta.change_count==4,"exact tail block delta");require(delta.assembled_arcs==4&&delta.output_edges==4&&delta.retained_blocks==count*4-4&&delta.flow_vertices<=8,"tail work independent of unchanged output size");require(delta.output_tree_nodes<256,"logarithmic changed paths");
 const auto&newgraph=static_cast<const showai_boundary::Owner*>(showai_boundary::owner(state.data()))->slots[next.slot].snapshot.get()->graph;for(uint32_t i=0;i<count*4-4;i++)require(newgraph.edges.same_chunk(i,old.edges),"unaffected actual immutable block retained");
 SABoundaryBlockChange changes[4];require(sa_boundary_copy_block_changes(state.data(),next,0,4,changes,4)==0,"copy only four tail changes");for(const auto&change:changes){require(change.before_edges==1&&change.after_edges==1&&change.before.curve!=change.after.curve,"reused pool slot never aliases retired curve identity");SABoundaryEdge previous{},updated{};require(sa_boundary_copy_block_edges(state.data(),a,change.before,0,1,&previous,1)==0&&sa_boundary_copy_block_edges(state.data(),next,change.after,0,1,&updated,1)==0,"old and new exact block buffers coexist");require(std::memcmp(&previous,&updated,sizeof previous)!=0,"tail actually changed data");require(sa_boundary_copy_block_edges(state.data(),next,change.before,0,1,&updated,1)==SA_INK_INVALID,"retired block identity cannot read replacement");}
 SABoundaryBlock cold{};require(sa_boundary_copy_blocks(state.data(),next,0,1,&cold,1)==0&&cold.edges==1&&cold.reserved==0&&!std::memcmp(&cold.key,&before[0].after,sizeof cold.key),"cold enumeration exposes actual retained block without rebuilding");SABoundaryBlockChange small[4];std::memset(small,0x5a,sizeof small);require(sa_boundary_copy_block_changes(state.data(),next,0,4,small,3)==SA_INK_CAPACITY,"delta copy capacity explicit");for(auto x:small)for(auto byte:std::vector<unsigned char>((unsigned char*)&x,(unsigned char*)&x+sizeof x))require(byte==0x5a,"failed copy leaves whole output unchanged");require(sa_boundary_copy_blocks(state.data(),next,0,1,(SABoundaryBlock*)arena.data(),1)==SA_INK_INVALID,"cold export cannot alias private arena");
 SABoundaryEdge stable{},again{};require(sa_boundary_copy_block_edges(state.data(),a,before[0].after,0,1,&stable,1)==0&&sa_boundary_copy_block_edges(state.data(),next,before[0].after,0,1,&again,1)==0&&!std::memcmp(&stable,&again,sizeof stable),"retained key returns identical derived bytes");uint32_t needed=0;require(sa_boundary_copy_block_parameter(state.data(),next,before[0].after,0,nullptr,0,&needed)==0&&needed>4,"retained original exact root certificate");std::vector<uint32_t>words(needed);require(sa_boundary_copy_block_parameter(state.data(),next,before[0].after,0,words.data(),needed,&needed)==0,"copy block certificate");
 if(f){require(std::fwrite(&count,4,1,f)==1&&std::fwrite(&actual_capacity,sizeof actual_capacity,1,f)==1&&std::fwrite(&initial,sizeof initial,1,f)==1&&std::fwrite(&delta,sizeof delta,1,f)==1&&std::fwrite(changes,sizeof changes,1,f)==1&&std::fwrite(&stable,sizeof stable,1,f)==1&&std::fwrite(&needed,4,1,f)==1&&std::fwrite(words.data(),4,needed,f)==needed,"write actual parity");std::fclose(f);}
 if(count==32){path.fill=SA_BOUNDARY_EVENODD;SABoundaryLease reset{};require(sa_boundary_prepare(state.data(),&next,&path,1,sources.data(),count,commands.data(),count*5,&reset)==0,"explicit changed fill full capture");SABoundaryBlocksSnapshot reset_info{};require(sa_boundary_blocks_snapshot(state.data(),reset,&reset_info)==0&&reset_info.reset==1&&reset_info.base_generation==next.generation,"full reset binds exact previous generation");require(sa_boundary_copy_block_edges(state.data(),reset,before[0].after,0,1,&again,1)==SA_INK_INVALID,"old full-prepare epoch cannot alias same curve slot and revision");require(sa_boundary_copy_block_edges(state.data(),a,before[0].after,0,1,&again,1)==0&&!std::memcmp(&again,&stable,sizeof stable),"full reset leaves old lease immutable");require(sa_boundary_release(state.data(),reset)==0,"release reset lease");}
 require(sa_boundary_release(state.data(),a)==0&&sa_boundary_release(state.data(),next)==0&&sa_boundary_destroy(state.data())==0,"release complete owned graph");std::printf("BOUNDARY_ACTUAL_RETAINED_BLOCKS_OK sources=%u retained=%llu arcs=%llu output=%llu flow=%llu nodes=%llu\n",count,(unsigned long long)delta.retained_blocks,(unsigned long long)delta.assembled_arcs,(unsigned long long)delta.output_edges,(unsigned long long)delta.flow_vertices,(unsigned long long)delta.output_tree_nodes);
}
